package com.keqi.reminder;

import org.json.*;
import java.time.*;

public final class WorkspaceTests {
    private static int checks;
    private static void check(boolean condition,String label){checks++;if(!condition)throw new AssertionError(label);}
    private static Workspace peer(Workspace host) throws Exception {Workspace peer=new Workspace(new JSONObject());peer.join(host.id());peer.receive(host.snapshot(-1));return peer;}
    private static void exchange(Workspace host,Workspace phone) throws Exception {JSONArray queue=phone.pending();for(int i=0;i<queue.length();i++)host.apply(queue.getJSONObject(i),true);JSONArray observations=phone.observations();for(int i=0;i<observations.length();i++)host.acceptObservation(observations.getJSONObject(i),phone.device());phone.observationsAcknowledged(observations);phone.receive(host.snapshot(phone.save().optLong("cursor",-1)));}
    public static void main(String[] args) throws Exception {
        Workspace host=new Workspace(new JSONObject());String id=new TaskService(host,true).command("createTask",new JSONObject().put("title","买笔记本")).getString("id");
        check(new TaskService(host,true).tasks(false).length()==1,"manual todo saved without a deadline");
        Workspace phone=peer(host);TaskService computerTasks=new TaskService(host,true),phoneTasks=new TaskService(phone,false);
        phoneTasks.command("updateTask",new JSONObject().put("id",id).put("note","准备课堂笔记"));computerTasks.command("updateTask",new JSONObject().put("id",id).put("priority",3));exchange(host,phone);
        check(host.get(id).getString("note").equals("准备课堂笔记")&&phone.get(id).getInt("priority")==3,"different fields merge");check(phone.pending().length()==0,"committed receipt drains upload queue");
        phoneTasks.command("updateTask",new JSONObject().put("id",id).put("note","手机上的修改"));computerTasks.command("updateTask",new JSONObject().put("id",id).put("note","电脑上的修改"));exchange(host,phone);
        check(host.get(id).getJSONArray("conflicts").length()==1,"concurrent note versions preserved");phoneTasks.command("resolveConflict",new JSONObject().put("id",id).put("note","合并后的备注").put("bases",phone.get(id).getJSONObject("fieldVersions")));exchange(host,phone);check(host.get(id).getJSONArray("conflicts").length()==0,"explicit conflict resolution");
        phoneTasks.command("addSubtask",new JSONObject().put("parent",id).put("title","列清单"));computerTasks.command("addSubtask",new JSONObject().put("parent",id).put("title","确认型号"));exchange(host,phone);check(new TaskService(host,true).tasks(false).getJSONObject(0).getJSONArray("subtasks").length()==2,"independent steps both survive");
        phoneTasks.command("updateTask",new JSONObject().put("id",id).put("note","离线备注"));computerTasks.command("deleteTask",new JSONObject().put("id",id));exchange(host,phone);check(new TaskService(host,true).tasks(false).length()==0&&new TaskService(host,true).tasks(true).length()==1,"delete intent survives concurrent editing");computerTasks.command("restoreTask",new JSONObject().put("id",id));check(new TaskService(host,true).tasks(false).length()==1,"explicit restore");
        Workspace other=new Workspace(new JSONObject());JSONObject op=phone.pending().optJSONObject(0);phoneTasks.command("updateTask",new JSONObject().put("id",id).put("priority",1));op=phone.pending().getJSONObject(0);try{other.apply(op,true);throw new AssertionError("wrong workspace accepted");}catch(IllegalArgumentException expected){checks++;}
        host.apply(op,true);long revision=host.revision();host.apply(op,true);check(host.revision()==revision,"lost receipt retry is idempotent");
        Workspace a=peer(host),b=peer(host);JSONObject c=new JSONObject().put("key","chaoxing:101:202").put("platform","chaoxing").put("title","概率论").put("courseId","101").put("classId","202");JSONObject t=new JSONObject().put("id","old-local-a").put("platform","chaoxing").put("courseKey",c.getString("key")).put("sourceId","901").put("phase","submit").put("title","第三章").put("kind","homework").put("status","pending").put("due",1800000000000L);
        a.observe("chaoxing","user-7",new JSONArray().put(c),new JSONArray().put(t),false,false);t.put("id","old-local-b");b.observe("chaoxing","user-7",new JSONArray().put(c),new JSONArray().put(t),false,false);exchange(host,a);exchange(host,b);check(host.list("platform").length()==1,"source identity deduplicates independent local task IDs");
        String courseId=host.list("course").getJSONObject(0).getString("id");computerTasks.command("applyCourseChoices",new JSONObject().put("remove",new JSONArray().put(courseId)));t.put("id","old-local-b");b.observe("chaoxing","user-7",new JSONArray().put(c),new JSONArray().put(t),false,false);exchange(host,b);check(host.get(courseId).getBoolean("removed"),"platform rediscovery cannot restore excluded course");
        Workspace unpaired=new Workspace(new JSONObject());String personal=new TaskService(unpaired,false).command("createTask",new JSONObject().put("title","离线新增")).getString("id");unpaired.join(host.id());exchange(host,unpaired);check(host.get(personal)!=null,"first pairing preserves pre-existing offline todo");
        JSONObject monthly=new JSONObject().put("frequency","monthly").put("interval",1).put("start","2026-01-31T09:00").put("timezone","Asia/Shanghai").put("shortMonth","last");long from=Instant.parse("2026-02-01T00:00:00Z").toEpochMilli(),until=Instant.parse("2026-03-01T00:00:00Z").toEpochMilli();JSONArray repeats=Repeats.instances("series",monthly,from,until);check(repeats.length()==1&&repeats.getJSONObject(0).getString("slot").equals("2026-02-28"),"month-end uses last calendar day");monthly.put("shortMonth","skip");check(Repeats.instances("series",monthly,from,until).length()==0,"month-end skip rule");
        Workspace restart=new Workspace(phone.save());check(restart.get(id).getString("note").equals("离线备注"),"round-trip persistence preserves user state");
        Workspace offline=peer(host);String offlineId=new TaskService(offline,false).command("createTask",new JSONObject().put("title","先拉取再上传")).getString("id");offline.receive(host.snapshot(-1));check(offline.get(offlineId)!=null&&offline.pending().length()==1,"pull cannot erase unacknowledged local create");exchange(host,offline);check(host.get(offlineId)!=null,"replayed offline create is accepted once");
        Workspace importing=new Workspace(new JSONObject());importing.observe("chaoxing","user-7",new JSONArray().put(c),new JSONArray().put(t),true,false);String linked=new TaskService(importing,false).command("createTask",new JSONObject().put("title","课程计划").put("courseKey",importing.canonical(c.getString("key")))).getString("id");new TaskService(importing,false).command("addSubtask",new JSONObject().put("parent",importing.canonical(t.getString("id"))).put("title","平台任务步骤"));importing.join(host.id());exchange(host,importing);check(host.get(linked).getString("courseKey").equals(courseId),"joining remaps manual course association");check(host.list("subtask").toString().contains("平台任务步骤")&&host.list("subtask").toString().contains(host.list("platform").getJSONObject(0).getString("id")),"joining retains platform subtask parent");
        Workspace recurring=new Workspace(new JSONObject());JSONObject daily=new JSONObject().put("frequency","daily").put("start","2030-01-01T09:00").put("timezone","Asia/Shanghai");String series=new TaskService(recurring,true).command("createTask",new JSONObject().put("title","晨读").put("repeat",daily)).getString("id");long future=Instant.parse("2030-01-01T00:00:00Z").toEpochMilli();Repeats.materialize(recurring,future,future+7*86400000L,true);Workspace second=peer(recurring);Repeats.materialize(second,future,future+7*86400000L,false);exchange(recurring,second);check(recurring.list("manual").length()==7,"same recurrence slots never duplicate");JSONObject first=recurring.list("manual").getJSONObject(0);new TaskService(recurring,true).command("updateTask",new JSONObject().put("id",first.getString("id")).put("manualDue",future+3600000L));check(recurring.get(first.getString("id")).getLong("manualDue")==future+3600000L,"instance date edit overrides generated baseline");
        new TaskService(recurring,true).command("changeSeries",new JSONObject().put("id",series).put("paused",true));check(new TaskService(recurring,true).tasks(false).getJSONObject(0).getBoolean("reminderSuppressed"),"pause suppresses existing future instance reminders");new TaskService(recurring,true).command("changeSeries",new JSONObject().put("id",series).put("paused",false).put("rule",new JSONObject().put("frequency","weekly").put("start","2030-01-03T09:00").put("timezone","Asia/Shanghai")));Repeats.materialize(recurring,future,future+7*86400000L,true);JSONArray active=new TaskService(recurring,true).tasks(false);int ordinary=0;for(int i=0;i<active.length();i++)if(!active.getJSONObject(i).optBoolean("seriesReplaced"))ordinary++;check(ordinary==3,"rule change hides untouched obsolete future instances");
        JSONObject dst=new JSONObject().put("frequency","daily").put("start","2026-03-08T02:30").put("timezone","America/New_York");JSONArray gap=Repeats.instances("dst",dst,Instant.parse("2026-03-08T00:00:00Z").toEpochMilli(),Instant.parse("2026-03-09T00:00:00Z").toEpochMilli());check(gap.getJSONObject(0).getLong("due")==Instant.parse("2026-03-08T07:00:00Z").toEpochMilli(),"DST gap moves to first valid local time");
        Workspace archiveHost=new Workspace(new JSONObject());String archiveId=archiveHost.create(new JSONObject().put("title","备注冲突"),true);Workspace archivePhone=peer(archiveHost);archiveHost.edit(archiveId,"manual",new JSONObject().put("note","版本 A"),true);archivePhone.edit(archiveId,"manual",new JSONObject().put("note","版本 B"),false);exchange(archiveHost,archivePhone);Workspace restored=new Workspace(new JSONObject());restored.importArchive(new JSONObject().put("format","keqi-data-v1").put("snapshot",archiveHost.snapshot(-1)),true);check(restored.get(archiveId).getJSONArray("conflicts").getJSONObject(0).getJSONArray("candidates").length()==2,"backup restoration preserves all conflict candidates");
        try{host.edit(id,"manual",new JSONObject().put("tags",new JSONArray().put(42)),true);throw new AssertionError("bad tag accepted");}catch(IllegalArgumentException expected){checks++;}
        try{host.edit(courseId,"course",new JSONObject().put("note","wrong type"),true);throw new AssertionError("course task fields accepted");}catch(IllegalArgumentException expected){checks++;}
        System.out.println("Shared task / sync checks passed: "+checks);
    }
}
